'use client';

import React from 'react';

/** Input state for the ChatInput. */
export type ChatInputState = 'streaming' | 'recording';

/** Visual variant for the ChatInput. */
export type ChatInputVariant = 'compact';

/** Props for the {@link ChatInput} component. */
export interface ChatInputProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'onSubmit'> {
  /** Current state of the input. */
  state?: ChatInputState;
  /** Visual variant. */
  variant?: ChatInputVariant;
  /** Placeholder text for the textarea. */
  placeholder?: string;
  /** Controlled value of the textarea. */
  value?: string;
  /** Called when the textarea value changes. */
  onValueChange?: (value: string) => void;
  /** Called when the user submits (Enter without Shift). */
  onSubmit?: (value: string) => void;
  /** Hint text displayed below the input. */
  hint?: string;
  /** Whether the textarea is disabled. */
  disabled?: boolean;
  /** Additional CSS class names. */
  className?: string;
  /** Extra action elements (e.g. mic button) rendered in the actions area. */
  actions?: React.ReactNode;
}

/**
 * AI prompt input with auto-resize textarea and action buttons.
 * Handles Enter-to-submit and Shift+Enter for newlines.
 */
export const ChatInput = React.forwardRef<HTMLDivElement, ChatInputProps>(
  (
    {
      state,
      variant,
      placeholder = 'Type a message...',
      value,
      onValueChange,
      onSubmit,
      hint,
      disabled,
      actions,
      className,
      ...rest
    },
    ref,
  ) => {
    const [internal, setInternal] = React.useState('');
    const text = value ?? internal;

    const handleChange = React.useCallback(
      (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        const v = e.target.value;
        if (value === undefined) setInternal(v);
        onValueChange?.(v);
      },
      [value, onValueChange],
    );

    const handleKeyDown = React.useCallback(
      (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
        if (e.key === 'Enter' && !e.shiftKey && onSubmit) {
          e.preventDefault();
          onSubmit(text);
          if (value === undefined) setInternal('');
        }
      },
      [text, onSubmit, value],
    );

    return (
      <div
        ref={ref}
        className={`sk-chat-input${className ? ` ${className}` : ''}`}
        data-state={state}
        data-variant={variant}
        {...rest}
      >
        <div className="sk-chat-input__wrapper">
          <textarea
            className="sk-chat-input__field"
            placeholder={placeholder}
            aria-label={placeholder}
            value={text}
            onChange={handleChange}
            onKeyDown={handleKeyDown}
            disabled={disabled || state === 'streaming'}
            rows={1}
          />
          {actions && <div className="sk-chat-input__actions">{actions}</div>}
        </div>
        {hint && <div className="sk-chat-input__hint">{hint}</div>}
      </div>
    );
  },
);

ChatInput.displayName = 'ChatInput';

/**
 * skeehn — ChatInput Component
 *
 * @component sk-chat-input
 * @variants  default | compact
 * @states    [data-state="streaming"|"recording"] | [data-loading] | [data-skeleton]
 * @slots     __wrapper __field __actions __mic __hint __dropzone __char-count
 * @a11y      aria-label on field, visible focus ring, disabled states
 * @design    SANS prose field, visible focus ring, taller target, distinct
 *            recording (pulsing red dot) vs streaming. Mono chrome (hint/count).
 */

.sk-chat-input {
  padding: var(--sk-space-3) 0;
  font-family: var(--sk-font-mono);
}

.sk-chat-input__wrapper {
  display: flex;
  align-items: flex-end;
  gap: var(--sk-space-2);
  padding: var(--sk-space-2);
  border: var(--sk-border);
  border-radius: var(--sk-radius-md);
  background: hsl(var(--sk-surface));
  transition: border-color var(--sk-transition);
  position: relative;
}

/* Visible focus ring (a11y) */
.sk-chat-input__wrapper:focus-within {
  border-color: hsl(var(--sk-accent));
  outline: var(--sk-focus-ring);
  outline-offset: var(--sk-focus-ring-offset);
}

/* Subtle dither texture on focus */
.sk-chat-input__wrapper:focus-within::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--sk-dither-pattern);
  background-size: 32px 32px;
  background-repeat: repeat;
  opacity: var(--sk-dither-opacity-subtle);
  pointer-events: none;
  border-radius: inherit;
}

/* Field — SANS prose, comfortable target */
.sk-chat-input__field {
  flex: 1;
  border: none;
  outline: none;
  box-shadow: none;
  background: transparent;
  resize: none;
  min-height: 2.5rem;
  max-height: 12rem;
  overflow-y: auto;
  padding: var(--sk-space-2) var(--sk-space-1);
  font-family: var(--sk-font-sans);
  font-size: 0.9rem;
  line-height: 1.5;
  color: hsl(var(--sk-foreground));
  field-sizing: content;
}
.sk-chat-input__field::placeholder { color: hsl(var(--sk-muted-foreground)); }

.sk-chat-input__actions {
  display: flex;
  gap: var(--sk-space-1);
  flex-shrink: 0;
  align-items: flex-end;
}

/* Mic / action buttons */
.sk-chat-input__mic {
  font-size: 1rem;
  line-height: 1;
  transition: color var(--sk-transition), transform var(--sk-transition);
}
.sk-chat-input__mic[data-mic-state="recording"] { color: hsl(var(--sk-destructive)); }

/* Hint — readable mono chrome */
.sk-chat-input__hint {
  margin-top: var(--sk-space-2);
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-xs);
  color: hsl(var(--sk-muted-foreground));
  text-align: center;
  letter-spacing: var(--sk-letter-spacing-wide);
}
.sk-chat-input__hint--recording { color: hsl(var(--sk-destructive)); }

/* Streaming — locked field, accent-tint border */
.sk-chat-input[data-state="streaming"] .sk-chat-input__wrapper {
  border-color: hsl(var(--sk-accent) / 0.5);
}
.sk-chat-input[data-state="streaming"] .sk-chat-input__field { opacity: 0.5; }

/* Recording — destructive border + pulsing red dot */
.sk-chat-input[data-state="recording"] .sk-chat-input__wrapper { border-color: hsl(var(--sk-destructive) / 0.7); }
.sk-chat-input[data-state="recording"] .sk-chat-input__wrapper::after {
  content: "";
  position: absolute;
  top: var(--sk-space-2);
  right: var(--sk-space-2);
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: hsl(var(--sk-destructive));
  box-shadow: 0 0 8px hsl(var(--sk-destructive) / 0.7);
  animation: sk-blink 1s steps(2) infinite;
}

/* Compact variant */
.sk-chat-input[data-variant="compact"] .sk-chat-input__wrapper { padding: var(--sk-space-1); }
.sk-chat-input[data-variant="compact"] .sk-chat-input__field { min-height: 2rem; }
.sk-chat-input[data-variant="compact"] .sk-chat-input__hint { display: none; }

/* File drop zone */
.sk-chat-input__dropzone {
  position: absolute;
  inset: 0;
  display: none;
  align-items: center;
  justify-content: center;
  background: hsl(var(--sk-accent) / 0.06);
  border: 2px dashed hsl(var(--sk-accent) / 0.5);
  border-radius: inherit;
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-xs);
  letter-spacing: var(--sk-letter-spacing-wide);
  color: hsl(var(--sk-accent));
  z-index: 10;
  pointer-events: none;
}
.sk-chat-input__wrapper[data-dragover] .sk-chat-input__dropzone { display: flex; }
.sk-chat-input__wrapper[data-dragover] { border-color: hsl(var(--sk-accent)); border-style: dashed; }

/* Character count — readable */
.sk-chat-input__char-count {
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-xs);
  color: hsl(var(--sk-muted-foreground) / 0.7);
  letter-spacing: var(--sk-letter-spacing-wide);
  text-align: right;
  padding-right: var(--sk-space-2);
  font-variant-numeric: tabular-nums;
}
.sk-chat-input__char-count[data-over-limit] { color: hsl(var(--sk-destructive)); }

/* Mention styling */
.sk-chat-input__mention {
  display: inline;
  background: hsl(var(--sk-accent) / 0.15);
  color: hsl(var(--sk-accent));
  padding: 0.05em 0.25em;
  border-radius: var(--sk-radius-control);
  font-weight: 600;
}

/* Loading & skeleton (centralized keyframes) */
.sk-chat-input[data-loading] .sk-chat-input__wrapper { pointer-events: none; opacity: 0.6; }
.sk-chat-input[data-loading] .sk-chat-input__wrapper::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--sk-dither-pattern);
  background-repeat: repeat;
  opacity: var(--sk-dither-opacity-subtle);
  animation: sk-pulse-dither 1.5s ease-in-out infinite;
  pointer-events: none;
}
.sk-chat-input[data-skeleton] .sk-chat-input__wrapper {
  pointer-events: none;
  background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-secondary)) 50%, hsl(var(--sk-muted)) 75%);
  background-size: 200% 100%;
  animation: sk-shimmer 1.8s ease-in-out infinite;
}
.sk-chat-input[data-skeleton] .sk-chat-input__field,
.sk-chat-input[data-skeleton] .sk-chat-input__actions { visibility: hidden; }

@media print { .sk-chat-input { display: none; } }

@media (prefers-reduced-motion: reduce) {
  .sk-chat-input__wrapper { transition: none; }
  .sk-chat-input[data-state="recording"] .sk-chat-input__wrapper::after { animation: none; }
  .sk-chat-input[data-loading] .sk-chat-input__wrapper::after { animation: none; }
  .sk-chat-input[data-skeleton] .sk-chat-input__wrapper { animation: none; background: hsl(var(--sk-muted)); }
}
